      if (!b) { out.unknownContrast++; continue; }
      if (!fg || fg.a <= 0.9) continue;
      const [hi, lo] = [lum(fg.rgb), lum(b)].sort((x, y) => y - x);
      const ratio = (hi + 0.05) / (lo + 0.05);
